{"content":"import re

class InterpreterError(Exception):
    pass

class SyntaxError(InterpreterError):
    pass

class NameError(InterpreterError):
    pass

class ZeroDivisionError(InterpreterError):
    pass

def manual_tokenize(code):
    tokens = []
    i = 0
    while i < len(code):
        if code[i].isspace():
            i += 1
            continue
        if code[i:i+2] == '**':
            tokens.append(('POW', '**'))
            i += 2
            continue

        if code[i].isdigit() or (code[i] == '.' and i+1 < len(code) and code[i+1].isdigit()):
            start = i
            has_dot = False
            while i < len(code) and (code[i].isdigit() or code[i] == '.'):
                if code[i] == '.':
                    if has_dot: break
                    has_dot = True
                i += 1
            tokens.append(('NUMBER', code[start:i]))
            continue

        char = code[i]
        if char in ('+', '-', '*', '/', '%', '=', '(', ')', ','):
            token_map = {'+': 'PLUS', '-': 'MINUS', '*': 'MUL', '/': 'DIV', 
                         '%': 'MOD', '=': 'EQ', '(': 'LPAREN', ')': 'RPAREN', ',': 'COMMA'}
            tokens.append((token_map[char], char))
            i += 1
            continue

        if char.isalpha() or char == '_':
            start = i
            while i < len(code) and (code[i].isalnum() or code[i] == '_'):
                i += 1
            tokens.append(('ID', code[start:i]))
            continue

        raise SyntaxError(f"Unknown character: {char}")
    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self):
        token = self.peek()
        if token is None: raise SyntaxError("Unexpected end of input")
        self.pos += 1
        return token

    def expect(self, expected_type):
        token = self.peek()
        if token is None or token[0] != expected_type:
            raise SyntaxError(f"Expected {expected_type}, got {token[1] if token else 'EOF'}")
        return self.consume()

    def parse_assignment_or_expr(self):
        if self.peek() and self.peek()[0] == 'ID':
            name = self.peek()[1]
            # Look ahead to check if it's an assignment
            idx = self.pos + 1
            is_assign = False
            while idx < len(self.tokens):
                if self.tokens[idx][0] == 'EQ':
                    is_assign = True
                    break
                if self.tokens[idx][0] in ('PLUS', 'MINUS', 'MUL', 'DIV', 'MOD', 'POW', 'LPAREN', 'RPAREN', 'COMMA'):
                    break
                idx += 1

            if is_assign:
                self.consume() # ID
                self.consume() # EQ
                expr = self.parse_expression()
                return ('ASSIGN', name, expr)

        expr = self.parse_expression()
        return expr

    def parse_expression(self):
        return self.parse_additive()

    def parse_additive(self):
        node = self.parse_multiplicative()
        while self.peek() and self.peek()[0] in ('PLUS', 'MINUS'):
            op = self.consume()[1]
            right = self.parse_multiplicative()
            node = ('BINOP', op, node, right)
        return node

    def parse_multiplicative(self):
        node = self.parse_unary()
        while self.peek() and self.peek()[0] in ('MUL', 'DIV', 'MOD'):
            op = self.consume()[1]
            right = self.parse_unary()
            node = ('BINOP', op, node, right)
        return node

    def parse_unary(self):
        if self.peek() and self.peek()[0] in ('PLUS', 'MINUS'):
            op = self.consume()[1]
            right = self.parse_exponentiation()
            return ('UNARY', op, right)
        return self.parse_exponentiation()

    def parse_exponentiation(self):
        node = self.parse_primary()
        if self.peek() and self.peek()[0] == 'POW':
            self.consume()
            right = self.parse_exponentiation()
            return ('BINOP', '**', node, right)
        return node

    def parse_primary(self):
        token = self.peek()
        if token is None:
            raise SyntaxError("Unexpected end of expression")

        if token[0] == 'NUMBER':
            val = self.consume()[1]
            return ('NUMBER', float(val) if '.' in val else int(val))

        if token[0] == 'LPAREN':
            self.consume()
            expr = self.parse_expression()
            self.expect('RPAREN')
            return expr

        if token[0] == 'ID':
            name = self.consume()[1]
            if self.peek() and self.peek()[0] == 'LPAREN':
                self.consume()
                args = []
                if self.peek() and self.peek()[0] != 'RPAREN':
                    args.append(self.parse_expression())
                    while self.peek() and self.peek()[0] == 'COMMA':
                        self.consume()
                        args.append(self.parse_expression())
                self.expect('RPAREN')
                return ('CALL', name, args)
            return ('VAR', name)

        raise SyntaxError(f"Unexpected token: {token[1]}")

def evaluate(node, env):
    if node[0] == 'NUMBER':
        return node[1]
    elif node[0] == 'VAR':
        name = node[1]
        if name not in env:
            raise NameError(f"NameError: name '{name}' is not defined")
        return env[name]
    elif node[0] == 'BINOP':
        op = node[1]
        left = evaluate(node[2], env)
        right = evaluate(node[3], env)
        if op == '+': return left + right
        if op == '-': return left - right
        if op == '*': return left * right
        if op == '/':
            if right == 0: raise ZeroDivisionError("ZeroDivisionError: division by zero")
            return left / right
        if op == '%':
            if right == 0: raise ZeroDivisionError("ZeroDivisionError: division by zero")
            return left % right
        if op == '**': return left ** right
    elif node[0] == 'UNARY':
        val = evaluate(node[2], env)
        return -val if node[1] == '-' else val
    elif node[0] == 'CALL':
        name = node[1]
        args = [evaluate(arg, env) for arg in node[2]]
        if name == 'min': return min(args)
        if name == 'max': return max(args)
        if name == 'abs': return abs(args[0])
        raise NameError(f"NameError: name '{name}' is not defined")
    elif node[0] == 'ASSIGN':
        name = node[1]
        val = evaluate(node[2], env)
        env[name] = val
        return val
    raise SyntaxError("Invalid AST node")

def calistir(program: str):
    env = {}
    last_val = None

    clean_lines = []
    for line in program.splitlines():
        line = line.split('#')[0].strip()
        if line:
            clean_lines.append(line)

    if not clean_lines:
        return None

    all_statements = []
    for line in clean_lines:
        statement_parts = []
        current_part = ""
        paren_depth = 0
        for char in line:
            if char == '(': paren_depth += 1
            elif char == ')': paren_depth -= 1
            if char == ';' and paren_depth == 0:
                if current_part.strip():
                    statement_parts.append(current_part.strip())
                current_part = ""
            else:
                current_part += char
        if current_part.strip():
            statement_parts.append(current_part.strip())
        all_statements.extend(statement_parts)

    for stmt in all_statements:
        tokens = manual_tokenize(stmt)
        if not tokens: continue
        parser = Parser(tokens)
        node = parser.parse_assignment_or_expr()
        if parser.pos < len(tokens):
            raise SyntaxError("Unexpected tokens after expression")
        last_val = evaluate(node, env)

    return last_val
